 28	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
 29	public record ReservationReceipt(
 30	        String title,
 31	        long reservationId,
 32	        String guestName,
 33	        String guestCpf,
 34	        int roomNumber,
 35	        RoomType roomType,
 36	        LocalDate checkIn,
 37	        LocalDate checkOut,
 38	        int nights,
 39	        BigDecimal subtotal,
 40	        BigDecimal discount,
 41	        BigDecimal total) {
 42	
 43	    public ReservationReceipt(Reservation reservation, Room room) {
 44	        this(
 45	                "Comprovante de reserva",
 46	                reservation.id(),
 47	                reservation.guest().name(),
 48	                reservation.guest().cpf(),
 49	                room.number(),
 50	                room.type(),
 51	                reservation.checkIn(),
 52	                reservation.checkOut(),
 53	                reservation.price().nights(),
 54	                reservation.price().subtotal(),
 55	                reservation.price().discount(),
 56	                reservation.price().total());
 57	    }
 58	
 59	    public String text() {
 60	        StringBuilder text = new StringBuilder();
 61	        text.append(title).append(" nº ").append(reservationId).append('\n');
 62	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
 63	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 64	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 65	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 66	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 67	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 68	        if (discount.signum() > 0) {
 69	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 70	        }
 71	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
 72	        return text.toString();
 73	    }
 74	}

